import React, { useState } from 'react';
import Table from './components/Table';
import './App.css';

function App() {
    const [tables, setTables] = useState([]);

    const addTable = () => {
        const newTableId = tables.length + 1;
        setTables(prevTables => [...prevTables, newTableId]);
    };

    return (
        <div className="App">
            <div className="sidebar">
                <button className="add-table-btn" onClick={addTable}>Add Table</button>
                <div className="table-list">
                    {tables.map(tableId => (
                        <div key={tableId} className="table-item">
                            Table {tableId}
                        </div>
                    ))}
                </div>
            </div>
            <div className="main-content">
                {tables.map(tableId => (
                    <Table key={tableId} tableId={tableId} />
                ))}
            </div>
        </div>
    );
}

export default App;
